package com.wenwen.ai.parse;
/** 专用追加事件；没有原问句、患者列表或模型文案。 */
public final class ParseAuditEvent {
    private final String eventId,questionRef,traceId,action,conditionSummary,engine,parseStatus,fallbackReason,schemaVersion,ruleVersion;
    private final String modelVersion,promptVersion;
    private final long actorDoctorId,durationMs,createdAtMs;
    private final boolean applied;
    public ParseAuditEvent(String eventId,String questionRef,String traceId,long actorDoctorId,String action,String conditionSummary,String engine,String parseStatus,boolean applied,String fallbackReason,long durationMs,String schemaVersion,String ruleVersion,long createdAtMs){this(eventId,questionRef,traceId,actorDoctorId,action,conditionSummary,engine,parseStatus,applied,fallbackReason,durationMs,schemaVersion,ruleVersion,createdAtMs,null,null);}
    public ParseAuditEvent(String eventId,String questionRef,String traceId,long actorDoctorId,String action,String conditionSummary,String engine,String parseStatus,boolean applied,String fallbackReason,long durationMs,String schemaVersion,String ruleVersion,long createdAtMs,String modelVersion,String promptVersion){this.modelVersion=modelVersion;this.promptVersion=promptVersion;this.eventId=eventId;this.questionRef=questionRef;this.traceId=traceId;this.actorDoctorId=actorDoctorId;this.action=action;this.conditionSummary=conditionSummary;this.engine=engine;this.parseStatus=parseStatus;this.applied=applied;this.fallbackReason=fallbackReason;this.durationMs=durationMs;this.schemaVersion=schemaVersion;this.ruleVersion=ruleVersion;this.createdAtMs=createdAtMs;}
    public String getEventId(){return eventId;} public String getQuestionRef(){return questionRef;} public String getTraceId(){return traceId;} public long getActorDoctorId(){return actorDoctorId;} public String getAction(){return action;} public String getConditionSummary(){return conditionSummary;} public String getEngine(){return engine;} public String getParseStatus(){return parseStatus;} public boolean isApplied(){return applied;} public String getFallbackReason(){return fallbackReason;} public long getDurationMs(){return durationMs;} public String getSchemaVersion(){return schemaVersion;} public String getRuleVersion(){return ruleVersion;} public String getModelVersion(){return modelVersion;} public String getPromptVersion(){return promptVersion;} public long getCreatedAtMs(){return createdAtMs;}
}
